  (* [comment removed for export] *)
  Ltac dv_kill K := try (exfalso; try rewrite signed_small in K by lia; try rewrite wz_unsigned in K by lia; try rewrite b8_unsigned in K by lia; lia).

  (* [comment removed for export] *)
  Ltac ulit :=
    match goal with |- context [bv_unsigned (Z_to_bv 64 ?x)] =>
      lazymatch x with
      | context [bv_unsigned (Z_to_bv 64 _)] => fail
      | _ => rewrite (unsigned_lit x) by lia
      end
    end.
  Ltac ulits := rewrite ?Z.shiftl_mul_pow2 by lia;
    try change (2 ^ 5) with 32; try change (2 ^ 3) with 8; try change (2 ^ 2) with 4; try change (2 ^ 1) with 2;
    repeat ulit.

